import { IncidentStatus } from '../../models/MedicalIncident';

export type IncidentFormTabId =
  | 'incident'
  | 'staff_analysis'
  | 'management_analysis'
  | 'chat'
  | 'documents';

export type IncidentFormHintVariant = 'guide' | 'readonly';

export interface IncidentFormHint {
  variant: IncidentFormHintVariant;
  icon: string;
  message: string;
  actionLabel?: string;
  actionTab?: IncidentFormTabId;
}

export interface IncidentFormHintContext {
  isNew: boolean;
  status?: IncidentStatus;
  activeTab: IncidentFormTabId;
  isTab1ReadOnly: boolean;
  isAnalysisReadOnly: boolean;
  isAnalysisTab: boolean;
  isMismatchReport: boolean;
  hasHeaderActions: boolean;
  canSubmitReport: boolean;
  canStartAnalysis: boolean;
  canSaveAnalysis: boolean;
  canEditWhenComplete: boolean;
  showFeedbackSection: boolean;
  hasStaffFeedback: boolean;
  isOwner: boolean;
}

const READONLY_HINT: IncidentFormHint = {
  variant: 'readonly',
  icon: 'fas fa-lock',
  message:
    'Chế độ chỉ xem. Bạn không có quyền thực hiện thao tác nào ở trạng thái hiện tại.',
};

function isContentTab(ctx: IncidentFormHintContext): boolean {
  return (
    ctx.activeTab === 'incident' ||
    ctx.activeTab === 'staff_analysis' ||
    ctx.activeTab === 'management_analysis'
  );
}

function isCurrentTabReadOnly(ctx: IncidentFormHintContext): boolean {
  if (ctx.activeTab === 'incident') return ctx.isTab1ReadOnly;
  if (ctx.isAnalysisTab) return ctx.isAnalysisReadOnly;
  return false;
}

/** Status-aware banner — readonly only when no toolbar actions remain. */
export function resolveIncidentFormHint(ctx: IncidentFormHintContext): IncidentFormHint | null {
  if (!isContentTab(ctx)) return null;

  if (!ctx.hasHeaderActions && isCurrentTabReadOnly(ctx)) {
    return READONLY_HINT;
  }

  if (ctx.hasHeaderActions) {
    if ((ctx.isNew || ctx.status === IncidentStatus.Draft) && ctx.activeTab === 'incident') {
      if (ctx.canSubmitReport && !ctx.isTab1ReadOnly) {
        return {
          variant: 'guide',
          icon: 'fas fa-paper-plane',
          message:
            'Hoàn tất thông tin sự cố, sau đó nhấn Gửi báo cáo trên thanh công cụ để gửi.',
        };
      }
    }

    if (ctx.status === IncidentStatus.Submitted && !ctx.isMismatchReport && ctx.activeTab === 'incident') {
      if (ctx.canStartAnalysis) {
        return {
          variant: 'guide',
          icon: 'fas fa-play',
          message:
            'Sự cố đã gửi. Nhấn Bắt đầu phân tích trên thanh công cụ để chuyển sang giai đoạn phân tích.',
        };
      }
      if (ctx.isOwner && ctx.canSubmitReport && !ctx.isTab1ReadOnly) {
        return {
          variant: 'guide',
          icon: 'fas fa-info-circle',
          message:
            'Bạn có thể cập nhật thông tin trước khi quản lý bắt đầu phân tích.',
        };
      }
    }

    if (ctx.status === IncidentStatus.InAnalysis && !ctx.isMismatchReport) {
      if (ctx.canSaveAnalysis && ctx.activeTab === 'incident') {
        return {
          variant: 'guide',
          icon: 'fas fa-search',
          message:
            'Sự cố đang phân tích. Mở tab Phân Tích Sự Cố hoặc Chuyên Gia Đánh Giá để nhập thông tin.',
          actionLabel: 'Mở Phân Tích Sự Cố',
          actionTab: 'staff_analysis',
        };
      }
    }

    if (
      (ctx.status === IncidentStatus.Resolved || ctx.status === IncidentStatus.Closed) &&
      ctx.canEditWhenComplete &&
      ctx.activeTab === 'incident'
    ) {
      return {
        variant: 'guide',
        icon: 'fas fa-edit',
        message:
          'Sự cố đã hoàn thành. Bạn có quyền chỉnh sửa — thay đổi thông tin rồi nhấn Cập nhật trên thanh công cụ.',
      };
    }

    if (
      (ctx.status === IncidentStatus.Resolved || ctx.status === IncidentStatus.Closed) &&
      ctx.canEditWhenComplete &&
      ctx.isAnalysisTab
    ) {
      return {
        variant: 'guide',
        icon: 'fas fa-edit',
        message:
          'Bạn có quyền chỉnh sửa phân tích sau hoàn thành. Lưu thay đổi trên thanh công cụ.',
      };
    }

    if (
      (ctx.status === IncidentStatus.Resolved || ctx.status === IncidentStatus.Closed) &&
      ctx.showFeedbackSection &&
      !ctx.hasStaffFeedback &&
      ctx.activeTab === 'incident'
    ) {
      return {
        variant: 'guide',
        icon: 'fas fa-star',
        message: 'Phân tích đã hoàn tất. Nhấn Đánh giá trên thanh công cụ để gửi phản hồi.',
      };
    }
  }

  if (!ctx.hasHeaderActions) {
    if (ctx.status === IncidentStatus.Submitted && ctx.activeTab === 'incident') {
      return {
        variant: 'guide',
        icon: 'fas fa-hourglass-half',
        message: 'Sự cố đã gửi và đang chờ quản lý bắt đầu phân tích.',
      };
    }

    if (ctx.status === IncidentStatus.InAnalysis && ctx.activeTab === 'incident') {
      return {
        variant: 'guide',
        icon: 'fas fa-hourglass-half',
        message: 'Sự cố đang được phân tích bởi quản lý hoặc nhân viên chuyên trách.',
      };
    }

    if (isCurrentTabReadOnly(ctx)) {
      return READONLY_HINT;
    }
  }

  return null;
}
