import React from 'react';
import { CollapsibleSection } from './CollapsibleSection';
import {
  ManagementAnalysis,
  NotificationStatus,
  InjurySeverityPatient,
  INJURY_SEVERITY_PATIENT_HINTS,
} from '../../../models/MedicalIncident';
import styles from './Tab4B_ManagementAnalysis.module.css';
import { TextArea, Input, RadioGroup, Checkbox } from '@linm-soft-org/linm-web-common-components';
import { IncidentUserSearchInput } from '../../../components/search/IncidentUserSearchInput';

interface Props {
  data: ManagementAnalysis;
  onChange: (patch: Partial<ManagementAnalysis>) => void;
  readOnly?: boolean;
  errors?: Record<string, string>;
}

// ── Tri-state radio options (Có / Không / Không ghi nhận) ───────────────────

const NOTIFY_OPTIONS: { value: NotificationStatus; label: string }[] = [
  { value: NotificationStatus.Yes,         label: 'Có' },
  { value: NotificationStatus.No,          label: 'Không' },
  { value: NotificationStatus.NotRecorded, label: 'Không ghi nhận' },
];

// ── Severity rows (NC level → letter radio) ────────────────────────────────
interface SeverityRowProps {
  rowId: string;
  ncLabel: string;
  letters: InjurySeverityPatient[];
  current: string;
  onChange: (v: string) => void;
  readOnly?: boolean;
}

const SeverityRow: React.FC<SeverityRowProps> = ({ rowId, ncLabel, letters, current, onChange, readOnly }) => (
  <tr className={styles.severityRow}>
    <td className={styles.severityNcCell}>{ncLabel}</td>
    <td className={styles.severityLettersCell}>
      <RadioGroup
        id={`injury-severity-${rowId}`}
        name="injurySeverityPatient"
        value={current}
        onChange={onChange}
        disabled={readOnly}
        layout="horizontal"
        compact
        options={letters.map((letter) => ({
          value: letter,
          label: letter.replace(/^NC\d_/, ''),
          tooltip: INJURY_SEVERITY_PATIENT_HINTS[letter],
        }))}
      />
    </td>
  </tr>
);

// ── Main component ─────────────────────────────────────────────────────────
export const Tab4BManagementAnalysis: React.FC<Props> = ({ data, onChange, readOnly, errors = {} }) => (
  <div className={styles.container}>

    {/* ── Section I ─────────────────────────────────────────────────────────────────────── */}
    <CollapsibleSection
      title="I. Đánh giá của Trưởng nhóm chuyên gia"
      errorKeys={['findingsSummary', 'discussedWithReporter', 'matchesOfficialRecommendations']}
      errors={errors}
    >

      <TextArea
        id="mgmt-findings-summary"
        label="Mô tả kết quả phát hiện được (không lặp lại các mô tả sự cố)"
        value={data.findingsSummary}
        onChange={(e) => onChange({ findingsSummary: e.target.value })}
        rows={4}
        fullWidth
        readOnly={readOnly}
        required
        error={errors.findingsSummary}
      />

      <RadioGroup
        id="mgmt-discussed-with-reporter"
        label="Đã thảo luận đưa ra khuyến cáo/hướng xử lý với người báo cáo"
        name="discussedWithReporter"
        options={NOTIFY_OPTIONS}
        value={data.discussedWithReporter ?? ''}
        onChange={(v) => onChange({ discussedWithReporter: v as NotificationStatus })}
        disabled={readOnly}
      />
      {errors.discussedWithReporter && <p style={{ color: 'var(--color-error, #dc2626)', fontSize: '0.75rem', marginTop: '2px', marginBottom: '4px' }}>{errors.discussedWithReporter}</p>}

      <RadioGroup
        id="mgmt-matches-official-recommendations"
        label="Phù hợp với các khuyến cáo chính thức được ban hành"
        name="matchesOfficialRecommendations"
        options={NOTIFY_OPTIONS}
        value={data.matchesOfficialRecommendations ?? ''}
        onChange={(v) => onChange({ matchesOfficialRecommendations: v as NotificationStatus })}
        disabled={readOnly}
      />
      {errors.matchesOfficialRecommendations && <p style={{ color: 'var(--color-error, #dc2626)', fontSize: '0.75rem', marginTop: '2px', marginBottom: '4px' }}>{errors.matchesOfficialRecommendations}</p>}

      <TextArea
        id="mgmt-specific-recommendations"
        label="Ghi cụ thể các khuyến cáo:"
        value={data.specificRecommendations}
        onChange={(e) => onChange({ specificRecommendations: e.target.value })}
        rows={3}
        fullWidth
        readOnly={readOnly}
      />
    </CollapsibleSection>

    {/* ── Section II: Đánh giá mức độ tổn thương ──────────────────────────── */}
    <CollapsibleSection
      title="II. Đánh giá mức độ tổn thương"
      errorKeys={['injurySeverityPatient']}
      errors={errors}
    >

      <div className={styles.severityGrid}>

        {/* Left: Trên người bệnh */}
        <div>
          <p className={styles.severityColumnTitle}>Trên người bệnh</p>
          <table className={styles.severityTable}>
            <tbody>
              <SeverityRow
                rowId="nc0"
                ncLabel="1. Chưa xảy ra (NC0)"
                letters={[InjurySeverityPatient.NC0_A]}
                current={data.injurySeverityPatient}
                onChange={(v) => onChange({ injurySeverityPatient: v })}
                readOnly={readOnly}
              />
              <SeverityRow
                rowId="nc1"
                ncLabel="2. Tổn thương nhẹ (NC1)"
                letters={[InjurySeverityPatient.NC1_B, InjurySeverityPatient.NC1_C, InjurySeverityPatient.NC1_D]}
                current={data.injurySeverityPatient}
                onChange={(v) => onChange({ injurySeverityPatient: v })}
                readOnly={readOnly}
              />
              <SeverityRow
                rowId="nc2"
                ncLabel="3. Tổn thương trung bình (NC2)"
                letters={[InjurySeverityPatient.NC2_E, InjurySeverityPatient.NC2_F, InjurySeverityPatient.NC2_G]}
                current={data.injurySeverityPatient}
                onChange={(v) => onChange({ injurySeverityPatient: v })}
                readOnly={readOnly}
              />
              <SeverityRow
                rowId="nc3"
                ncLabel="4. Tổn thương nặng (NC3)"
                letters={[InjurySeverityPatient.NC3_H, InjurySeverityPatient.NC3_I]}
                current={data.injurySeverityPatient}
                onChange={(v) => onChange({ injurySeverityPatient: v })}
                readOnly={readOnly}
              />
            </tbody>
          </table>
        </div>

        {/* Right: Trên tổ chức */}
        <div>
          <p className={styles.severityColumnTitle}>Trên tổ chức</p>
          <div className={styles.orgImpactGrid}>
            <Checkbox id="injury-org-property-damage" label="Tổn hại tài sản"                       checked={data.injuryOrgPropertyDamage}     onChange={(e) => onChange({ injuryOrgPropertyDamage: e.target.checked })}     disabled={readOnly} />
            <Checkbox id="injury-org-increased-resources" label="Tăng nguồn lực phục vụ cho người bệnh" checked={data.injuryOrgIncreasedResources} onChange={(e) => onChange({ injuryOrgIncreasedResources: e.target.checked })} disabled={readOnly} />
            <Checkbox id="injury-org-media-attention" label="Quan tâm của truyền thông"              checked={data.injuryOrgMediaAttention}     onChange={(e) => onChange({ injuryOrgMediaAttention: e.target.checked })}     disabled={readOnly} />
            <Checkbox id="injury-org-patient-complaint" label="Khiếu nại của người bệnh"               checked={data.injuryOrgPatientComplaint}   onChange={(e) => onChange({ injuryOrgPatientComplaint: e.target.checked })}   disabled={readOnly} />
            <Checkbox id="injury-org-reputation-damage" label="Tổn hại danh tiếng"                     checked={data.injuryOrgReputationDamage}   onChange={(e) => onChange({ injuryOrgReputationDamage: e.target.checked })}   disabled={readOnly} />
            <Checkbox id="injury-org-legal-intervention" label="Can thiệp của pháp luật"                checked={data.injuryOrgLegalIntervention}  onChange={(e) => onChange({ injuryOrgLegalIntervention: e.target.checked })}  disabled={readOnly} />
            <Checkbox id="injury-org-other" label="Khác"                                    checked={data.injuryOrgOther}              onChange={(e) => onChange({ injuryOrgOther: e.target.checked })}              disabled={readOnly} />
          </div>
        </div>

      </div>
      {errors.injurySeverityPatient && (
        <p style={{ color: 'var(--color-error, #dc2626)', fontSize: '0.75rem', marginTop: '4px', paddingLeft: '4px' }}>
          {errors.injurySeverityPatient}
        </p>
      )}
    </CollapsibleSection>

    {/* ── Section III: Kết luận ────────────────────────────────────────────── */}
    <CollapsibleSection title="III. Kết luận" errorKeys={['rootCauseAnalysis', 'correctiveActions']} errors={errors}>
      <TextArea
        id="mgmt-root-cause-analysis"
        label="Kết luận"
        value={data.rootCauseAnalysis}
        onChange={(e) => onChange({ rootCauseAnalysis: e.target.value })}
        rows={4}
        fullWidth
        readOnly={readOnly}
        required
        error={errors.rootCauseAnalysis}
      />
      <TextArea
        id="mgmt-corrective-actions"
        label="Kết luận nguyên nhân gốc rễ"
        value={data.correctiveActions}
        onChange={(e) => onChange({ correctiveActions: e.target.value })}
        rows={4}
        fullWidth
        readOnly={readOnly}
        required
        error={errors.correctiveActions}
      />
      <Input
        id="mgmt-expert-email"
        label="Email chuyên trách"
        type="email"
        value={data.expertEmail ?? ''}
        onChange={(e) => onChange({ expertEmail: e.target.value })}
        fullWidth
        readOnly={readOnly}
      />
    </CollapsibleSection>

    {/* ── Sign-off ─────────────────────────────────────────────────────────────────────── */}
    <CollapsibleSection title="Ký xác nhận" errorKeys={['analysedById', 'analysisDate']} errors={errors}>
      <div className={styles.row2}>
        {readOnly ? (
          <Input
            id="mgmt-analysed-by-name"
            label="Tên"
            value={data.analysedBy}
            readOnly
            fullWidth
          />
        ) : (
          <IncidentUserSearchInput
            label="Tên"
            showLabel
            value={data.analysedById}
            staffId={data.analysedByCode}
            fullName={data.analysedBy}
            onChange={(userId, staffId, fullName) =>
              onChange({ analysedById: userId, analysedByCode: staffId, analysedBy: fullName })
            }
            disabled={readOnly}
            required
            error={errors.analysedById}
          />
        )}
        <Input
          id="mgmt-leader-title"
          label="Chức danh"
          value={data.leaderTitle}
          onChange={(e) => onChange({ leaderTitle: e.target.value })}
          fullWidth
          readOnly={readOnly}
        />
      </div>
      <div className={styles.row2}>
        <Input
          id="mgmt-analysis-date"
          label="Ngày"
          type="date"
          value={data.analysisDate ?? ''}
          onChange={(e) => onChange({ analysisDate: e.target.value })}
          fullWidth
          readOnly={readOnly}
          required
          error={errors.analysisDate}
        />
        <Input
          id="mgmt-analysis-time"
          label="Giờ"
          type="time"
          value={data.analysisTime}
          onChange={(e) => onChange({ analysisTime: e.target.value })}
          fullWidth
          readOnly={readOnly}
        />
      </div>
    </CollapsibleSection>
  </div>
);

